  1→/* Party-facing dispute form. W15 layout pass: the Ryde app's canvas rhythm —
  2→   720px shell, white step cards floating on the pastel paper, pill eyebrow
  3→   chip, normal-flow in-card action bar. Colours stay the W10 brand tokens. */
  4→
  5→:root {
  6→  --ink: #31373E;
  7→  --muted: #5A6470;
  8→  --line: #E5E0DC;
  9→  --paper: #F7DDE3;
 10→  --card: #ffffff;
 11→  --accent: #E93864;
 12→  --accent-ink: #ffffff;
 13→  --error: #C0392B;
 14→  --ok: #1EB848;
 15→  --tint: #FFF0F3;
 16→  --float-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
 17→}
 18→
 19→* {
 20→  box-sizing: border-box;
 21→}
 22→
 23→body {
 24→  margin: 0;
 25→  background: var(--paper);
 26→  color: var(--ink);
 27→  font-family: Poppins, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
 28→  line-height: 1.5;
 29→}
 30→
 31→.party-shell {
 32→  max-width: 720px;
 33→  margin: 0 auto;
 34→  padding: 2.5rem 1.25rem 5rem;
 35→}
 36→
 37→.party-header .eyebrow {
 38→  display: inline-block;
 39→  margin: 0;
 40→  padding: 0.35rem 0.9rem;
 41→  font-size: 0.75rem;
 42→  font-weight: 600;
 43→  letter-spacing: 0.14em;
 44→  color: var(--accent);
 45→  background: var(--tint);
 46→  border: 1px solid var(--accent);
 47→  border-radius: 9999px;
 48→}
 49→
 50→.party-header h1 {
 51→  margin: 0.25rem 0 0.5rem;
 52→  font-size: 2.25rem;
 53→  font-weight: 600;
 54→}
 55→
 56→.intro {
 57→  margin: 0 0 0.25rem;
 58→  color: var(--muted);
 59→}
 60→
 61→.demo-note {
 62→  margin: 0 0 1.5rem;
 63→  padding: 0.6rem 0.9rem;
 64→  font-size: 0.85rem;
 65→  color: var(--muted);
 66→  background: var(--tint);
 67→  border: 1px solid var(--line);
 68→  border-radius: 14px;
 69→}
 70→
 71→.step {
 72→  background: var(--card);
 73→  border: 1px solid var(--line);
 74→  border-radius: 20px;
 75→  padding: 1.5rem;
 76→  margin-bottom: 1.5rem;
 77→  box-shadow: var(--float-shadow);
 78→}
 79→
 80→.step h2 {
 81→  display: flex;
 82→  align-items: center;
 83→  gap: 0.6rem;
 84→  margin: 0 0 0.9rem;
 85→  font-size: 1.15rem;
 86→  font-weight: 600;
 87→}
 88→
 89→.step-number {
 90→  display: inline-flex;
 91→  align-items: center;
 92→  justify-content: center;
 93→  width: 1.7rem;
 94→  height: 1.7rem;
 95→  border-radius: 50%;
 96→  background: var(--accent);
 97→  color: var(--accent-ink);
 98→  font-size: 0.9rem;
 99→}
100→
101→.hint {
102→  margin: -0.4rem 0 0.9rem;
103→  color: var(--muted);
104→  font-size: 0.9rem;
105→}
106→
107→.option-grid {
108→  display: grid;
109→  gap: 0.6rem;
110→}
111→
112→.option-card {
113→  text-align: left;
114→  width: 100%;
115→  padding: 1rem 1.1rem;
116→  border: 1px solid var(--line);
117→  border-radius: 16px;
118→  background: var(--card);
119→  font: inherit;
120→  cursor: pointer;
121→  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
122→}
123→
124→.option-card:hover {
125→  border-color: var(--accent);
126→  transform: translateY(-2px);
127→  box-shadow: var(--float-shadow);
128→}
129→
130→.option-card.selected {
131→  background: var(--tint);
132→  border: 2px solid var(--accent);
133→  box-shadow: none;
134→}
135→
136→.choice-options {
137→  display: flex;
138→  gap: 0.6rem;
139→  margin-bottom: 0.6rem;
140→}
141→
142→.choice-button {
143→  flex: 1;
144→  border: 2px solid var(--line);
145→  background: var(--card);
146→  color: var(--ink);
147→  font-weight: 400;
148→}
149→
150→.choice-button:hover {
151→  border-color: var(--accent);
152→}
153→
154→.choice-button.selected {
155→  border-width: 3px;
156→  border-color: var(--accent);
157→  font-weight: 600;
158→}
159→
160→.elaborate {
161→  margin-top: 0.6rem;
162→}
163→
164→.trip-card strong {
165→  display: block;
166→}
167→
168→.trip-meta {
169→  display: block;
170→  color: var(--muted);
171→  font-size: 0.85rem;
172→}
173→
174→.loading {
175→  color: var(--muted);
176→}
177→
178→.field {
179→  margin-bottom: 1rem;
180→}
181→
182→.field label {
183→  display: block;
184→  font-weight: 600;
185→  margin-bottom: 0.3rem;
186→}
187→
188→.field-note {
189→  font-weight: 400;
190→  color: var(--muted);
191→  font-size: 0.8rem;
192→}
193→
194→textarea,
195→input[type="text"],
196→input[type="number"] {
197→  width: 100%;
198→  padding: 0.7rem 0.9rem;
199→  border: 1px solid var(--line);
200→  border-radius: 14px;
201→  font: inherit;
202→  resize: vertical;
203→}
204→
205→textarea:focus,
206→input:focus {
207→  outline: 2px solid var(--accent);
208→  outline-offset: 1px;
209→  box-shadow: 0 0 0 4px var(--tint);
210→}
211→
212→button:focus-visible {
213→  outline: 2px solid var(--accent);
214→  outline-offset: 2px;
215→}
216→
217→.step-actions {
218→  display: flex;
219→  justify-content: flex-end;
220→  gap: 0.6rem;
221→  margin-top: 1rem;
222→  padding: 0.75rem 0 0.25rem;
223→  position: static;
224→  background: var(--card);
225→  border-top: 1px solid var(--line);
226→  border-radius: 0 0 20px 20px;
227→}
228→
229→button {
230→  font: inherit;
231→  font-weight: 600;
232→  padding: 0.7rem 1.5rem;
233→  border-radius: 29px;
234→  border: 1px solid var(--line);
235→  background: var(--card);
236→  cursor: pointer;
237→}
238→
239→button.primary {
240→  background: var(--accent);
241→  border-color: var(--accent);
242→  color: var(--accent-ink);
243→}
244→
245→button:disabled {
246→  opacity: 0.5;
247→  cursor: not-allowed;
248→}
249→
250→button:not(:disabled):hover {
251→  filter: brightness(0.97);
252→}
253→
254→.error {
255→  color: var(--error);
256→  margin: 0.6rem 0 0;
257→}
258→
259→.outcome-message {
260→  background: var(--paper);
261→  border: 1px solid var(--line);
262→  border-radius: 12px;
263→  padding: 0.9rem 1rem;
264→}
265→
266→.reference {
267→  color: var(--muted);
268→}
269→
270→.reference strong {
271→  color: var(--ink);
272→  letter-spacing: 0.03em;
273→}
274→
275→.status-line {
276→  color: var(--muted);
277→  font-size: 0.9rem;
278→}
279→
280→#question-boxes .field label {
281→  white-space: pre-line;
282→}
283→
284→/* W15 feedback follow-up: driver-only clearance for the claim amount helper. */
285→#form-steps[data-filed-by="driver"] #claim-amount + .hint {
286→  margin-top: 0.5rem;
287→}
288→
289→/* W15 feedback follow-up: the driver filing header's secondary links read as
290→   quiet outlined pills; the middle-dot separators stay as plain text. */
291→.party-header:has(+ #form-steps[data-filed-by="driver"]) > p:last-child {
292→  display: flex;
293→  flex-wrap: wrap;
294→  align-items: center;
295→  gap: 0.5rem;
296→}
297→
298→.party-header:has(+ #form-steps[data-filed-by="driver"]) > p:last-child a {
299→  display: inline-flex;
300→  align-items: center;
301→  min-height: 44px;
302→  max-width: 100%;
303→  padding: 0.5rem 1rem;
304→  background: var(--card);
305→  border: 1px solid var(--line);
306→  border-radius: 9999px;
307→  color: var(--ink);
308→  text-decoration: none;
309→  white-space: normal;
310→  overflow-wrap: anywhere;
311→}
312→
313→.party-header:has(+ #form-steps[data-filed-by="driver"]) > p:last-child a:hover {
314→  background: var(--tint);
315→  border-color: var(--accent);
316→  color: var(--ink);
317→}
318→
319→.party-header:has(+ #form-steps[data-filed-by="driver"]) > p:last-child a:focus-visible {
320→  background: var(--tint);
321→  border-color: var(--accent);
322→  color: var(--ink);
323→  outline: 2px solid var(--accent);
324→  outline-offset: 2px;
325→}
326→
327→/* W31: every navigation link inside the party shell now shares the driver
328→   header's quiet outlined-pill treatment, including the links the status and
329→   account pages render. */
330→.party-shell a {
331→  display: inline-flex;
332→  align-items: center;
333→  min-height: 44px;
334→  max-width: 100%;
335→  padding: 0.5rem 1rem;
336→  background: var(--card);
337→  border: 1px solid var(--line);
338→  border-radius: 9999px;
339→  color: var(--ink);
340→  text-decoration: none;
341→  white-space: normal;
342→  overflow-wrap: anywhere;
343→}
344→
345→.party-shell a:hover {
346→  background: var(--tint);
347→  border-color: var(--accent);
348→  color: var(--ink);
349→}
350→
351→.party-shell a:focus-visible {
352→  background: var(--tint);
353→  border-color: var(--accent);
354→  color: var(--ink);
355→  outline: 2px solid var(--accent);
356→  outline-offset: 2px;
357→}
358→
359→/* W31 follow-up: both filing headers share one compact wrapped navigation
360→   paragraph; the smaller text applies only to these filing links. */
361→.party-header > .party-nav {
362→  display: flex;
363→  flex-wrap: wrap;
364→  align-items: center;
365→  gap: 0.5rem;
366→  margin: 1rem 0;
367→}
368→
369→.party-header > .party-nav a {
370→  font-size: 0.9rem;
371→}
372→
373→/* W30 compact shared filing frame: while the filing form is on screen the shell
374→   fills the viewport as one flex column — header, form, fine print — so every
375→   step's actions sit at the bottom of the screen. The header and footer scroll
376→   internally on a short pane; the form region takes what is left. The receipt
377→   hides the form, so the frame stops applying and the page scrolls normally. */
378→.filing-shell:has(#form-steps:not([hidden])) {
379→  display: flex;
380→  flex-direction: column;
381→  height: 100vh;
382→  height: 100dvh;
383→  padding: 0.5rem 1.25rem;
384→  gap: 0.5rem;
385→}
386→
387→/* Page scrolling is locked only while the filing form is visible; the receipt
388→   and every other page keep their own scroll. */
389→body:has(.filing-shell #form-steps:not([hidden])) {
390→  overflow: hidden;
391→}
392→
393→/* The header stays above the card, capped so a short pane keeps room for the
394→   form (45% of the frame, never below 5rem, never leaving under 15rem). It
395→   scrolls internally when its copy does not fit. */
396→.filing-shell:has(#form-steps:not([hidden])) > .party-header {
397→  flex: 0 0 auto;
398→  max-height: max(5rem, min(45%, calc(100% - 15rem)));
399→  overflow-y: auto;
400→}
401→
402→.filing-shell:has(#form-steps:not([hidden])) > .party-header h1 {
403→  font-size: 1.25rem;
404→  line-height: 1.2;
405→  margin: 0.25rem 0;
406→}
407→
408→.filing-shell:has(#form-steps:not([hidden])) > .party-header .eyebrow {
409→  font-size: 0.65rem;
410→  padding: 0.1rem 0.5rem;
411→}
412→
413→.filing-shell:has(#form-steps:not([hidden])) > .party-header .intro {
414→  font-size: 0.85rem;
415→  margin: 0;
416→}
417→
418→.filing-shell:has(#form-steps:not([hidden])) > .party-header > .party-nav {
419→  margin: 0.375rem 0 0;
420→}
421→
422→/* The form, the visible step and the details form are nested flex columns;
423→   only the scrolling region inside them grows or shrinks. */
424→.filing-shell:has(#form-steps:not([hidden])) > #form-steps,
425→.filing-shell:has(#form-steps:not([hidden])) #form-steps > .step:not([hidden]),
426→.filing-shell:has(#form-steps:not([hidden])) #details-form {
427→  flex: 1 1 auto;
428→  min-height: 0;
429→  display: flex;
430→  flex-direction: column;
431→}
432→
433→.filing-shell:has(#form-steps:not([hidden])) #form-steps > .step:not([hidden]) {
434→  margin: 0;
435→  padding: 0.75rem;
436→}
437→
438→.filing-shell:has(#form-steps:not([hidden])) .step h2 {
439→  margin-bottom: 0.5rem;
440→}
441→
442→.filing-shell:has(#form-steps:not([hidden])) #step-trip > .hint {
443→  margin: 0 0 0.5rem;
444→}
445→
446→/* The action bar stays in normal flow at the bottom of the card, outside the
447→   scrolling region, so it never overlays an option. */
448→.filing-shell:has(#form-steps:not([hidden])) .step-actions {
449→  flex: 0 0 auto;
450→  margin-top: 1rem;
451→  padding-top: 0.5rem;
452→}
453→
454→.filing-shell:has(#form-steps:not([hidden])) .step-actions button {
455→  font-size: 0.9rem;
456→  padding: 0.5rem 1rem;
457→  min-height: 44px;
458→}
459→
460→/* The scrolling field region: its padding keeps focus rings and hover lifts
461→   clear of the edge, and the equal negative margin keeps the fields aligned
462→   with the card's content box. */
463→.filing-shell .filing-fields {
464→  flex: 1 1 auto;
465→  min-height: 0;
466→  overflow-y: auto;
467→  overscroll-behavior: contain;
468→  padding: 0.5rem;
469→  margin: -0.5rem;
470→}
471→
472→/* Demo fine print at the bottom of the frame: plain, quiet text that scrolls
473→   internally on very short panes. */
474→.filing-shell .filing-fine-print {
475→  flex: 0 0 auto;
476→  max-height: 12%;
477→  overflow-y: auto;
478→  font-size: 0.75rem;
479→  color: var(--muted);
480→}
481→
482→.filing-shell .filing-fine-print p {
483→  margin: 0 0 0.25rem;
484→  padding: 0;
485→  border: 0;
486→  background: none;
487→  font-size: inherit;
488→}
489→
490→/* A current trip error replaces the list and its hint; the empty error card
491→   keeps its actions at the bottom edge. */
492→.filing-shell:has(#form-steps:not([hidden])) #step-trip:has(#trip-error:not([hidden])) > .hint {
493→  display: none;
494→}
495→
496→.filing-shell:has(#form-steps:not([hidden])) #step-trip:has(#trip-error:not([hidden])) #trip-options {
497→  display: none;
498→}
499→
500→.filing-shell:has(#form-steps:not([hidden])) #step-trip:has(#trip-error:not([hidden])) > .step-actions {
501→  margin-top: auto;
502→}
503→
504→/* W30: inside the frame the trip step is a plain flex column; the frame owns
505→   the viewport sizing, so the card only lets its list shrink and scroll. */
506→#step-trip:not([hidden]) {
507→  display: flex;
508→  flex-direction: column;
509→  min-height: 0;
510→}
511→
512→/* Only the trip list shrinks to fit the card; the heading, hint, error and the
513→   action bar keep their natural height. */
514→#step-trip > h2,
515→#step-trip > .hint,
516→#step-trip > .error,
517→#step-trip > .step-actions {
518→  flex: 0 0 auto;
519→}
520→
521→/* The trip list scrolls inside itself, so the Continue/Back bar stays in normal
522→   flow directly under it and never over an option. align-content and
523→   grid-auto-rows keep each card at its natural height instead of stretching to
524→   fill the region. Its padding keeps a lifted or selected card clear of the
525→   region edge, and the equal negative margin keeps the cards aligned with the
526→   card's content box. The background is two token-coloured layers: a card-coloured
527→   cover that scrolls with the content and hides the fade once the list is at its
528→   end, and a fade pinned to the region's bottom edge while more trips are below. */
529→#step-trip #trip-options {
530→  flex: 1 1 auto;
531→  min-height: 0;
532→  overflow-y: auto;
533→  overscroll-behavior: contain;
534→  align-content: start;
535→  grid-auto-rows: max-content;
536→  padding: 0.75rem;
537→  margin: -0.75rem;
538→  background:
539→    linear-gradient(var(--card), var(--card)) bottom / 100% 2.5rem local no-repeat,
540→    linear-gradient(to top, var(--line), transparent) bottom / 100% 2.5rem scroll no-repeat;
541→}
542→
543→/* W30: a landed card — the trip card, and the category card Back returns to —
544→   keeps a breath of air from the screen edge. */
545→#step-category, #step-trip {
546→  scroll-margin: 1.5rem 0;
547→}
